    17  #define USHORT_RANGE (1 << 16)
    18  #define BITMAP_SIZE (USHORT_RANGE >> 3)
    19
    20  static void
    21  bitmapFromData (
    22      const uint16_t* data,
    23      uint64_t        nData,
    24      uint8_t*        bitmap,
    25      uint16_t*       minNonZero,
    26      uint16_t*       maxNonZero)
    27  {
    28      uint16_t mnnz = BITMAP_SIZE - 1;
    29      uint16_t mxnz = 0;
    30
    31      for (int i = 0; i < BITMAP_SIZE; ++i)
    32          bitmap[i] = 0;
    33
    34      for (uint64_t i = 0; i < nData; ++i)
    35          bitmap[data[i] >> 3] |= (1 << (data[i] & 7));
    36
    37      bitmap[0] &= ~1; // zero is not explicitly stored in
    38                       // the bitmap; we assume that the
    39                       // data always contain zeroes
    40
    41      for (uint16_t i = 0; i < BITMAP_SIZE; ++i)
    42      {
    43          if (bitmap[i])
    44          {
    45              if (mnnz > i) mnnz = i;
    46              if (mxnz < i) mxnz = i;
    47          }
    48      }
    49      *minNonZero = mnnz;
    50      *maxNonZero = mxnz;
    51  }
    52
    53  static inline uint16_t
    54  forwardLutFromBitmap (const uint8_t* bitmap, uint16_t* lut)
    55  {
    56      uint16_t k = 0;
    57
    58      for (uint32_t i = 0; i < USHORT_RANGE; ++i)
    59      {
    60          if ((i == 0) || (bitmap[i >> 3] & (1 << (i & 7))))
    61              lut[i] = k++;
    62          else
    63              lut[i] = 0;
    64      }
    65
    66      return k - 1;
    67  }
    68
    69  static inline uint16_t
    70  reverseLutFromBitmap (const uint8_t* bitmap, uint16_t* lut)
    71  {
    72      uint32_t n, k = 0;
    73
    74      for (uint32_t i = 0; i < USHORT_RANGE; ++i)
    75      {
    76          if ((i == 0) || (bitmap[i >> 3] & (1 << (i & 7))))
    77              lut[k++] = (uint16_t) i;
    78      }
    79
    80      n = k - 1;
    81
    82      while (k < USHORT_RANGE)
    83          lut[k++] = 0;
    84
    85      return (uint16_t) n;
    86  }
    87
    88  static inline void
    89  applyLut (const uint16_t* lut, uint16_t* data, uint64_t nData)
    90  {
    91      for (uint64_t i = 0; i < nData; ++i)
    92          data[i] = lut[data[i]];
    93  }
