    95  /**************************************/
    96  //
    97  // Wavelet basis functions without modulo arithmetic; they produce
    98  // the best compression ratios when the wavelet-transformed data are
    99  // Huffman-encoded, but the wavelet transform works only for 14-bit
   100  // data (untransformed data values must be less than (1 << 14)).
   101  //
   102
   103  static inline void
   104  wenc14 (uint16_t a, uint16_t b, uint16_t* l, uint16_t* h)
   105  {
   106      int16_t as = (int16_t) a;
   107      int16_t bs = (int16_t) b;
   108
   109      int16_t ms = (as + bs) >> 1;
   110      int16_t ds = as - bs;
   111
   112      *l = (uint16_t) ms;
   113      *h = (uint16_t) ds;
   114  }
